20260406225449	{"CREATE POLICY \\"Entregadores can update orders linked to their deliveries\\"\nON public.pedidos\nFOR UPDATE\nTO authenticated\nUSING (\n  id IN (\n    SELECT pedido_id FROM public.entregas\n    WHERE entregador_id = auth.uid()\n    AND pedido_id IS NOT NULL\n  )\n)\nWITH CHECK (\n  id IN (\n    SELECT pedido_id FROM public.entregas\n    WHERE entregador_id = auth.uid()\n    AND pedido_id IS NOT NULL\n  )\n);"}		apikey@lovable.dev	\N	\N
