20260425181549	{"ALTER TABLE public.lojas ADD COLUMN IF NOT EXISTS categorias_ocultas JSONB DEFAULT '[]'::jsonb;\n\nCOMMENT ON COLUMN public.lojas.categorias_ocultas IS 'Lista de nomes de categorias padrÃ£o que o lojista deseja ocultar em sua loja.';"}		apikey@lovable.dev	\N	\N
20260425185607	{"-- Enable Realtime for the produtos table\nALTER TABLE public.produtos REPLICA IDENTITY FULL;\n\n-- Check if the table is already in the publication to avoid error\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 \n        FROM pg_publication_tables \n        WHERE pubname = 'supabase_realtime' \n        AND schemaname = 'public' \n        AND tablename = 'produtos'\n    ) THEN\n        ALTER PUBLICATION supabase_realtime ADD TABLE public.produtos;\n    END IF;\nEND $$;"}		apikey@lovable.dev	\N	\N
20260425191242	{"ALTER TABLE public.lojas ADD COLUMN valor_plano_exclusivo NUMERIC;\nCOMMENT ON COLUMN public.lojas.valor_plano_exclusivo IS 'Valor exclusivo do plano para esta loja, que sobrescreve o valor padrÃ£o do plano.';"}		apikey@lovable.dev	\N	\N
