20260504015957	{"-- Alterar o padrÃ£o das colunas para 0.5\nALTER TABLE public.lojas ALTER COLUMN margem_esquerda SET DEFAULT 0.5;\nALTER TABLE public.lojas ALTER COLUMN margem_direita SET DEFAULT 0.5;\n\n-- Atualizar registros existentes onde as margens estÃ£o como 0 (assumindo que 0 era o padrÃ£o anterior)\nUPDATE public.lojas \nSET margem_esquerda = 0.5 \nWHERE margem_esquerda = 0 OR margem_esquerda IS NULL;\n\nUPDATE public.lojas \nSET margem_direita = 0.5 \nWHERE margem_direita = 0 OR margem_direita IS NULL;"}		apikey@lovable.dev	\N	\N
