20260605155811	{"ALTER TABLE public.pedidos ADD COLUMN IF NOT EXISTS pdv_pedido_id UUID REFERENCES public.pdv_pedidos(id) ON DELETE SET NULL;\n\n-- Criar ou substituir a funÃ§Ã£o de trigger para sincronizar o numero_diario\nCREATE OR REPLACE FUNCTION public.sync_pedido_numero_diario()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.pdv_pedido_id IS NOT NULL THEN\n    -- Busca o numero_diario do pdv_pedido\n    SELECT numero_diario INTO NEW.numero_diario\n    FROM public.pdv_pedidos\n    WHERE id = NEW.pdv_pedido_id;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Adicionar trigger Ã  tabela pedidos\nDROP TRIGGER IF EXISTS tr_sync_pedido_numero_diario ON public.pedidos;\nCREATE TRIGGER tr_sync_pedido_numero_diario\nBEFORE INSERT ON public.pedidos\nFOR EACH ROW\nEXECUTE FUNCTION public.sync_pedido_numero_diario();"}		apikey@lovable.dev	\N	\N
