20260606172258	{"-- Primeiro, vamos garantir que o trigger tr_sync_pedido_numero_diario seja executado ANTES do trg_set_numero_diario\n-- para que ele possa atribuir o numero_diario do PDV e o trg_set_numero_diario veja que jÃ¡ existe um valor.\n\n-- No PostgreSQL, os triggers sÃ£o executados em ordem alfabÃ©tica.\n-- Atualmente: \n-- tr_sync_pedido_numero_diario (S)\n-- trg_set_numero_diario (T)\n-- A ordem jÃ¡ estÃ¡ correta (S vem antes de T).\n\n-- O problema Ã© que o trg_set_numero_diario provavelmente nÃ£o verifica se o NEW.numero_diario jÃ¡ estÃ¡ preenchido.\n-- Vamos ajustar a funÃ§Ã£o set_numero_diario para respeitar um nÃºmero jÃ¡ atribuÃ­do.\n\nCREATE OR REPLACE FUNCTION public.set_numero_diario()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  next_num integer;\n  max_pedidos integer;\n  max_pdv integer;\n  store_id uuid;\nBEGIN\n  -- Se jÃ¡ houver um nÃºmero (atribuÃ­do por outro trigger como o de sync do PDV), mantÃ©m ele.\n  IF NEW.numero_diario IS NOT NULL AND NEW.numero_diario > 0 THEN\n    RETURN NEW;\n  END IF;\n\n  -- Get max from pedidos\n  SELECT COALESCE(MAX(numero_diario), 0)\n  INTO max_pedidos\n  FROM public.pedidos\n  WHERE lojista_id = NEW.lojista_id\n    AND DATE(created_at AT TIME ZONE 'America/Sao_Paulo') = DATE(NOW() AT TIME ZONE 'America/Sao_Paulo');\n\n  -- Get the store id for this owner\n  SELECT id INTO store_id FROM public.lojas WHERE user_id = NEW.lojista_id LIMIT 1;\n\n  -- Get max from pdv_pedidos\n  SELECT COALESCE(MAX(numero_diario), 0)\n  INTO max_pdv\n  FROM public.pdv_pedidos\n  WHERE loja_id = store_id\n    AND DATE(created_at AT TIME ZONE 'America/Sao_Paulo') = DATE(NOW() AT TIME ZONE 'America/Sao_Paulo');\n\n  next_num := GREATEST(max_pedidos, max_pdv) + 1;\n  NEW.numero_diario := next_num;\n  RETURN NEW;\nEND;\n$function$;\n\n-- Vamos ajustar tambÃ©m a funÃ§Ã£o do PDV para ser mais robusta e evitar conflitos.\nCREATE OR REPLACE FUNCTION public.set_numero_diario_pdv()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  next_num integer;\n  max_pedidos integer;\n  max_pdv integer;\n  store_user_id uuid;\nBEGIN\n  -- Se for um UPDATE e o nÃºmero jÃ¡ existir, nÃ£o altera\n  IF (TG_OP = 'UPDATE' AND OLD.numero_diario IS NOT NULL) THEN\n    RETURN NEW;\n  END IF;\n\n  -- Get the store owner's user_id from loja_id\n  SELECT user_id INTO store_user_id FROM public.lojas WHERE id = NEW.loja_id;\n\n  -- Get max numero_diario from pedidos for this store owner today\n  SELECT COALESCE(MAX(numero_diario), 0)\n  INTO max_pedidos\n  FROM public.pedidos\n  WHERE lojista_id = store_user_id\n    AND DATE(created_at AT TIME ZONE 'America/Sao_Paulo') = DATE(NOW() AT TIME ZONE 'America/Sao_Paulo');\n\n  -- Get max numero_diario from pdv_pedidos for this store today\n  SELECT COALESCE(MAX(numero_diario), 0)\n  INTO max_pdv\n  FROM public.pdv_pedidos\n  WHERE loja_id = NEW.loja_id\n    AND DATE(created_at AT TIME ZONE 'America/Sao_Paulo') = DATE(NOW() AT TIME ZONE 'America/Sao_Paulo');\n\n  next_num := GREATEST(max_pedidos, max_pdv) + 1;\n  NEW.numero_diario := next_num;\n  RETURN NEW;\nEND;\n$function$;\n"}		apikey@lovable.dev	\N	\N
